def read(name):
    """The bytes of one file of the step, checked against its pin."""
    b=zlib.decompress(base64.b64decode(FILES[name]))
    if hashlib.sha256(b).hexdigest()!=PINS[name]:raise ValueError('projection bundle: %s does not match its pin'%name)
    return b

def extract(dest):
    """Writes every file under dest (checked first, all or nothing) and returns the path of run_step.py."""
    got={k:read(k) for k in FILES}
    if sorted(got)!=sorted(PINS):raise ValueError('projection bundle: the file list does not match the pins')
    for k,b in got.items():
        p=os.path.join(dest,*k.split('/'));os.makedirs(os.path.dirname(p),exist_ok=True)
        with open(p,'wb') as f:f.write(b)
    return os.path.join(dest,'run_step.py')
